/** Runs every step in order. Each call owns its output and drift state. */
export async function runFlow(page: Page, vars: Vars, options: RunOptions = {}): Promise<Outputs> {
  validateInputs(vars);
  const run = options.run ?? createFlowRun();
  run.outputs = {};
  run.drift.length = 0;
  run.echoed = [];
  run.created = [];
  const outputs = run.outputs;
  try {
    await page.goto(options.startUrl ?? 'http://127.0.0.1:8069/');
    await test.step('01-open: Open http://127.0.0.1:8069/ and sign in with username \'admin\' and password \'admin\' (submit the login form). Then in Odoo, create a new customer contact named exactly \'{{runid}} Bench Customer\' with the City field set to \'Benchville\' (go to Contacts app, click New, fill the name and city, save). Verify the record saved and report the customer name and city shown on the saved record. Note: Odoo long-polls so the page is never network-idle - wait for concrete elements instead.', async () => {
      await steps['01-open'](page, { v1: vars.runid, v2: 'http://127.0.0.1:8069/', v3: `${vars.runid} Bench Customer`, v4: 'Benchville' }, outputs, run);
      console.log('[sitelooper step] 01-open');
    });
    await test.step('02-create: In Odoo, go to the Sales app and create a new quotation (RFQ) for the customer \'{{runid}} Bench Customer\' (the customer field is an autocomplete dropdown - type the name and actually click the matching option from the dropdown so it is properly selected). Add exactly ONE order line: pick any product from the product catalogue (again, the product field is an autocomplete - actually choose an option from the dropdown), with quantity 3. Let Odoo auto-fill the unit price from the product. Save the quotation. Then report: (a) the product name you chose, (b) the unit price Odoo filled in on that line, and (c) the Untaxed Amount the quotation shows. Do not confirm the quotation yet - leave it as a draft quotation. Note: Odoo long-polls so the page is never network-idle - wait for concrete elements instead.', async () => {
      await steps['02-create'](page, { v1: `${vars.runid} Bench Customer`, v2: vars.runid }, outputs, run);
      console.log('[sitelooper step] 02-create');
    });
    await test.step('03-open: In Odoo, open the existing draft quotation with reference {{02-create.quotation_reference}} (customer \'{{runid}} Bench Customer\', currently one line: \'{{02-create.product_name}}\' qty 3). Add a SECOND order line with a DIFFERENT product (the product field is an autocomplete dropdown - actually click an option from the dropdown; do not reuse Desk Combination) with quantity 2. Let Odoo auto-fill the unit price. Save the quotation. Then report: (a) the product name of the new second line, (b) the new Untaxed Amount the quotation shows, and (c) the Total. Keep the quotation in draft - do not confirm it. Note: Odoo long-polls so the page is never network-idle - wait for concrete elements instead.', async () => {
      await steps['03-open'](page, { v1: need(outputs, '02-create.quotation_reference', '03-open'), v2: `${vars.runid} Bench Customer`, v3: vars.runid, v4: outputs['02-create.product_name'] ?? '' }, outputs, run);
      console.log('[sitelooper step] 03-open');
    });
    await test.step('04-open: In Odoo, open the existing draft quotation {{02-create.quotation_reference}} (customer \'{{runid}} Bench Customer\'). It has two order lines: line 1 = \'{{02-create.product_name}}\' qty 3, line 2 = \'{{03-open.second_line_product}}\' qty 2. Change ONLY the first line\'s quantity from 3 to 5 (leave the second line at qty 2). Save the quotation. Then report: (a) the quantity shown on line 1 and line 2 after saving, and (b) the new Untaxed Amount the quotation shows, and (c) the Total. Keep the quotation in draft - do not confirm it. Note: Odoo long-polls so the page is never network-idle - wait for concrete elements instead.', async () => {
      await steps['04-open'](page, { v1: need(outputs, '02-create.quotation_reference', '04-open'), v2: `${vars.runid} Bench Customer`, v3: vars.runid, v4: outputs['02-create.product_name'] ?? '', v6: outputs['03-open.second_line_product'] ?? '' }, outputs, run);
      console.log('[sitelooper step] 04-open');
    });
    await test.step('05-open: In Odoo, open the existing draft quotation {{02-create.quotation_reference}} (customer \'{{runid}} Bench Customer\', two lines: Desk Combination qty 5, Office Chair qty 2, Untaxed Amount £2,390.00). Confirm the quotation by clicking the \'Confirm\' button so it becomes a sales order. Wait for the confirmation to take effect (the Confirm button disappears / status bar advances). Then report: (a) the order reference/name shown (e.g. {{02-create.quotation_reference}}), and (b) the status the app now shows in the status bar (e.g. \'Sales Order\'). Note: Odoo long-polls so the page is never network-idle - wait for concrete elements instead.', async () => {
      await steps['05-open'](page, { v1: need(outputs, '02-create.quotation_reference', '05-open'), v2: `${vars.runid} Bench Customer`, v3: vars.runid }, outputs, run);
      console.log('[sitelooper step] 05-open');
    });
    await test.step('06-open: In Odoo, open the confirmed sales order {{02-create.quotation_reference}} (customer \'{{runid}} Bench Customer\', status \'Sales Order\'). Cancel this sales order so nothing stays active: use the Cancel action from the order\'s menu (e.g. the \'Cancel\' button or the cog/Action menu -> Cancel, and confirm any dialog that appears). Wait for the cancellation to take effect. Then report: (a) the status the app shows in the status bar after cancelling (e.g. \'Cancelled\'), and (b) the order reference still shown ({{02-create.quotation_reference}}). Note: Odoo long-polls so the page is never network-idle - wait for concrete elements instead.', async () => {
      await steps['06-open'](page, { v1: need(outputs, '02-create.quotation_reference', '06-open'), v2: `${vars.runid} Bench Customer`, v3: vars.runid, v4: 'Sales Order' }, outputs, run);
      console.log('[sitelooper step] 06-open');
    });
    await test.step('07-change: Final verification in Odoo (read-only, do not change anything): (1) Open the customer contact \'{{runid}} Bench Customer\' in Contacts and report the name and City shown on the record. (2) Open the sales order {{02-create.quotation_reference}} and report the reference shown, the status bar\'s current status, and the Untaxed Amount shown. Do not edit or save anything. Note: Odoo long-polls so the page is never network-idle - wait for concrete elements instead.', async () => {
      await steps['07-change'](page, { v1: `${vars.runid} Bench Customer`, v2: vars.runid, v3: outputs['02-create.quotation_reference'] ?? '' }, outputs, run);
      console.log('[sitelooper step] 07-change');
    });
    return outputs;
  } finally {
    DRIFT.splice(0, DRIFT.length, ...run.drift);
  }
}
